// Normaliza telefone pro formato que a Meta espera: só dígitos, com 55 na frente (ex: 5511999998888)
function normalizaTelefone(raw) {
  if (!raw) return '';
  let digitos = String(raw).replace(/\D/g, '');
  digitos = digitos.replace(/^0+/, '');

  // já tem código do país (55) e tamanho compatível (DDD + 8 ou 9 dígitos) -> mantém
  if (digitos.startsWith('55') && (digitos.length === 12 || digitos.length === 13)) {
    return digitos;
  }
  // não tem código do país (só DDD + número) -> adiciona 55 na frente
  if (digitos.length === 10 || digitos.length === 11) {
    return '55' + digitos;
  }
  return digitos;
}

// Parseia um vCard cru (formato do contato nativo do WhatsApp) pra extrair nome e telefone.
// O LLM não consegue extrair isso de forma confiável direto do texto do vCard (campos tipo
// FN:, TEL:, waid= não são linguagem natural), então isso precisa ser feito por código.
function parseVcard(vcard) {
  const fnMatch = vcard.match(/FN:(.+)/);
  const waidMatch = vcard.match(/waid=(\d+)/);
  const telMatch = vcard.match(/TEL[^:]*:(.+)/);
  const nome = fnMatch ? fnMatch[1].trim() : null;
  const telefone = waidMatch ? waidMatch[1] : (telMatch ? telMatch[1].replace(/\D/g, '') : null);
  return { nome, telefone };
}

const input = $input.first().json;

let nomeIndicado = input.nome_indicado;
let telefoneIndicado = input.telefone_indicado;

// Se veio vcard_indicado preenchido, ele manda - o lead compartilhou o contato nativo do WhatsApp
if (input.vcard_indicado && String(input.vcard_indicado).trim() !== '') {
  const parsed = parseVcard(input.vcard_indicado);
  if (parsed.nome) nomeIndicado = parsed.nome;
  if (parsed.telefone) telefoneIndicado = parsed.telefone;
}

if (!nomeIndicado || !telefoneIndicado) {
  throw new Error('Não foi possível identificar nome e/ou telefone do indicado. Verifique o vcard_indicado ou nome_indicado/telefone_indicado recebidos.');
}

return [{
  json: {
    nome_indicado: nomeIndicado,
    telefone_indicado: normalizaTelefone(telefoneIndicado),
    nome_indicador: input.nome_indicador || 'Não identificado',
    telefone_indicador: normalizaTelefone(input.telefone_indicador),
    data_hora: new Date().toISOString()
  }
}];

